hint.textContent = '\u4EE3\u7406\u5DF2\u555F\u7528\uFF0C\u5339\u914D\u7DB2\u57DF\u540D\u7A31\u7684\u8ACB\u6C42\u5C07\u8D70\u4EE3\u7406\u670D\u52D9';
